<?php $j=find_job($_GET['id']??0);if(!$j){?><div class="page-container"><div class="empty-state"><h2>We couldn't find that role.</h2><a class="btn btn-dark" href="<?=url('jobs')?>">Back to jobs</a></div></div><?php return;} ?><div class="page-container narrow-container"><a class="back-link" href="<?=url('jobs')?>">← Back to opportunities</a><section class="job-detail-card"><div class="job-detail-head"><div class="company-logo logo-<?=e($j['color'])?> large-logo"><?=e($j['logo'])?></div><div class="job-detail-title"><span class="eyebrow eyebrow-dark"><?=e($j['company'])?> · <?=e($j['posted'])?></span><h1><?=e($j['title'])?></h1><p class="muted">⌖ <?=e($j['location'])?> <span class="meta-sep">·</span> <?=e($j['workplace'])?></p></div><?php if($j['featured']):?><span class="featured-label">✦ Featured</span><?php endif;?></div><div class="job-detail-meta"><div><small>Salary range</small><strong><?=e($j['salary'])?></strong></div><div><small>Employment</small><strong><?=e($j['type'])?></strong></div><div><small>Experience</small><strong><?=e($j['experience'])?></strong></div></div><div class="detail-section"><h2>About the role</h2><p><?=e($j['description'])?></p></div><div class="detail-section"><h2>What you'll bring</h2><div class="skill-list detail-skills"><?php foreach($j['skills'] as $s):?><span><?=e($s)?></span><?php endforeach;?></div></div><div class="apply-bar"><div><strong>Does this sound like your next step?</strong><small>Your application will be recorded in this demo session.</small></div><?php if(has_applied($j['id'])):?><button class="btn btn-success" disabled>✓ Applied</button><?php else:?><form method="post"><input type="hidden" name="action" value="apply"><input type="hidden" name="job_id" value="<?=$j['id']?>"><button class="btn btn-dark" type="submit">Apply now <span>↗</span></button></form><?php endif;?></div></section></div>